// ColorWithWhiteAlpha — Create component-based colors that are compatible with sRGB colorspace; these methods are effectively same as colorWithSRGBRed:... or colorWithGenericGamma22White:..., but provided for easier reuse of code that uses UIColor on iOS.  If red, green, blue, or saturation, brightness, or white values are outside of the 0..1 range, these will create colors in the extended sRGB (or for colorWithWhite:alpha:, extendedGenericGamma22GrayColorSpace) color spaces. This behavior is compatible with iOS UIColor.
func (c NSColorClass) ColorWithWhiteAlpha(white float64, alpha float64) NSColor {
	return NSColor{objc.ID(c.Class).Send(selColorWithWhiteAlpha, white, alpha)}
}
